def investigate(context, acquire):
    receipts = acquire("history")
    if not receipts:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        # put_mode: 0=IGNORE, 1=REPLACE, 2=UPSERT
        # trigger: bool, AFTER INSERT inserts one row into log
        # channel_mode: 0=changes(), 1=total_changes main, 2=total_changes main+other
        main = {}
        other = {}
        log = 0
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = {"main": False, "other": False}
        tx_snapshot = {}
        tx_log_snapshot = 0
        tx_changes_snapshot = 0
        tx_total_snapshot = 0
        tx_other_total_snapshot = 0
        tx_other_changes_snapshot = 0
        tx_other_log_snapshot = 0
        last_changes = 0

        def do_put(conn, key, value):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            table = main if conn == "main" else other
            changed = 0
            if put_mode == 0:
                if key not in table:
                    table[key] = value
                    changed = 1
            elif put_mode == 1:
                table[key] = value
                changed = 1
            else:
                if key in table:
                    if table[key] != value:
                        table[key] = value
                        changed = 1
                else:
                    table[key] = value
                    changed = 1
            if changed and trigger:
                log += 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed
            last_changes = changed

        def do_update(conn, key, value):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            table = main if conn == "main" else other
            changed = 0
            if key in table and table[key] != value:
                table[key] = value
                changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed
            last_changes = changed

        def do_delete(conn, key):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            table = main if conn == "main" else other
            changed = 0
            if key in table:
                del table[key]
                changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed
            last_changes = changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_put(conn, act["key"], act["value"])
            elif op == "update":
                do_update(conn, act["key"], act["value"])
            elif op == "delete":
                do_delete(conn, act["key"])
            elif op == "begin":
                in_tx[conn] = True
                if conn == "main":
                    tx_snapshot = dict(main)
                    tx_log_snapshot = log
                    tx_changes_snapshot = main_changes
                    tx_total_snapshot = main_total
                else:
                    tx_snapshot = dict(other)
                    tx_log_snapshot = log
                    tx_other_changes_snapshot = other_changes
                    tx_other_total_snapshot = other_total
            elif op == "commit":
                in_tx[conn] = False
            elif op == "rollback":
                if conn == "main":
                    main.clear()
                    main.update(tx_snapshot)
                    log = tx_log_snapshot
                    main_changes = tx_changes_snapshot
                    main_total = tx_total_snapshot
                else:
                    other.clear()
                    other.update(tx_snapshot)
                    log = tx_log_snapshot
                    other_changes = tx_other_changes_snapshot
                    other_total = tx_other_total_snapshot
                in_tx[conn] = False

        if channel_mode == 0:
            ch = main_changes
        elif channel_mode == 1:
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(main), sum(main.values())

    candidates = []
    for put_mode in range(3):
        for trigger in (False, True):
            for channel_mode in range(3):
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(r["actions"], put_mode, trigger, channel_mode)
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cnt)
        elif goal == "committed_sum":
            vals.add(sm)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
